<?php
require_once 'db.php';require_once 'auth.php';bejelentkezesSzukseges();$oldalCim='Riasztások';function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$q=trim($_GET['q']??'');$all=$_GET['allapot']??'mind';$where=[];$p=[];$oldal=max(1,(int)($_GET['oldal']??1));$meret=15;if($q!==''){ $where[]='(r.riasztas_szam LIKE ? OR r.helyszin LIKE ? OR r.telepules LIKE ? OR r.esemeny_tipus LIKE ? OR r.leiras LIKE ? OR r.jelzes_modja LIKE ? OR r.megjegyzes LIKE ?)';for($i=0;$i<7;$i++)$p[]="%$q%";}if(in_array($all,['uj','folyamatban','lezart','visszavont'],true)){ $where[]='r.allapot=?';$p[]=$all;}$w=$where?'WHERE '.implode(' AND ',$where):'';$st=$pdo->prepare("SELECT COUNT(*) FROM riasztasok r $w");$st->execute($p);$cnt=(int)$st->fetchColumn();$pages=max(1,(int)ceil($cnt/$meret));$oldal=min($oldal,$pages);$off=($oldal-1)*$meret;$st=$pdo->prepare("SELECT r.*, (SELECT COUNT(*) FROM bevetesek b WHERE b.riasztas_id=r.id) bevetes_db FROM riasztasok r $w ORDER BY r.datum DESC,r.riasztasi_ido DESC LIMIT $meret OFFSET $off");$st->execute($p);$rows=$st->fetchAll();$ma=(int)$pdo->query("SELECT COUNT(*) FROM riasztasok WHERE datum=CURDATE()")->fetchColumn();$uj=(int)$pdo->query("SELECT COUNT(*) FROM riasztasok WHERE allapot='uj'")->fetchColumn();$foly=(int)$pdo->query("SELECT COUNT(*) FROM riasztasok WHERE allapot='folyamatban'")->fetchColumn();$lez=(int)$pdo->query("SELECT COUNT(*) FROM riasztasok WHERE allapot='lezart'")->fetchColumn();require 'header.php';?><div class="page-title"><div><span class="eyebrow">ESEMÉNYNAPLÓ</span><h1>Riasztások</h1><p class="muted">A beérkezett riasztások nyilvántartása.</p></div><a href="riasztas_uj.php" class="btn btn-primary">+ Új riasztás</a></div><div class="stats-grid compact"><div class="stat-card"><span>Mai</span><strong><?=$ma?></strong></div><div class="stat-card"><span>Új</span><strong><?=$uj?></strong></div><div class="stat-card"><span>Folyamatban</span><strong><?=$foly?></strong></div><div class="stat-card"><span>Lezárt</span><strong><?=$lez?></strong></div></div><div class="card filters"><form method="get" class="filter-row"><input name="q" value="<?=e($q)?>" placeholder="Keresés szám, helyszín, esemény..."><select name="allapot"><option value="mind">Minden állapot</option><option value="uj" <?=$all==='uj'?'selected':''?>>Új</option><option value="folyamatban" <?=$all==='folyamatban'?'selected':''?>>Folyamatban</option><option value="lezart" <?=$all==='lezart'?'selected':''?>>Lezárt</option><option value="visszavont" <?=$all==='visszavont'?'selected':''?>>Visszavont</option></select><button class="btn btn-secondary">Szűrés</button><a class="btn btn-light" href="riasztasok.php">Alaphelyzet</a></form></div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Riasztás</th><th>Dátum / idő</th><th>Helyszín</th><th>Esemény</th><th>Bevetés</th><th>Állapot</th><th>Műveletek</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['riasztas_szam'])?></strong></td><td><?=e($r['datum'])?><br><span class="muted"><?=e(substr($r['riasztasi_ido'],0,5))?></span></td><td><?=e($r['helyszin'])?><?php if($r['telepules']):?><br><span class="muted"><?=e($r['telepules'])?></span><?php endif;?></td><td><?=e($r['esemeny_tipus'])?></td><td><?= (int)$r['bevetes_db'] ?></td><td><span class="badge badge-<?=e($r['allapot'])?>"><?=e(ucfirst($r['allapot']))?></span></td><td><div class="table-actions"><a class="btn btn-small btn-primary" href="bevetes_uj.php?riasztas_id=<?=$r['id']?>">Bevetés</a><a class="btn btn-small btn-secondary" href="riasztas_szerkeszt.php?id=<?=$r['id']?>">Szerkesztés</a><?php if(jogosultsag('admin')):?><a class="btn btn-small btn-danger" href="riasztas_torles.php?id=<?=$r['id']?>">Törlés</a><?php endif;?></div></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty-state">Nincs találat.</td></tr><?php endif;?></tbody></table></div></div><?php if($pages>1):?><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$oldal?'active':''?>" href="?<?=http_build_query(['q'=>$q,'allapot'=>$all,'oldal'=>$i])?>"><?=$i?></a><?php endfor;?></div><?php endif;?><?php require 'footer.php';?>